package main

import (
	"fmt"
	"reflect"
)

type Base struct{ ID int }
type Container struct {
	Base   // Anonymous embedded
	Title  string
}

func main() {
	c := Container{Base: Base{101}, Title: "Тест"}
	t := reflect.TypeOf(c)
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		fmt.Printf("Поле #%d: %-8s (Тип: %-12s, Anonymous: %t)\n", i, f.Name, f.Type, f.Anonymous)
	}
}

package main

import (
	"errors"
	"fmt"
)

type VirtualFile struct {
	name   string
	isOpen bool
}

func (f *VirtualFile) Open() error {
	if f.isOpen { return errors.New("файл уже открыт") }
	f.isOpen = true
	fmt.Printf("Файл %q открыт\n", f.name)
	return nil
}

func (f *VirtualFile) Close() error {
	if !f.isOpen { return errors.New("файл уже закрыт") }
	f.isOpen = false
	fmt.Printf("Файл %q закрыт\n", f.name)
	return nil
}

func main() {
	f := &VirtualFile{name: "app.log"}
	_ = f.Open()
	_ = f.Close()
}

