import "fmt"

type PaymentStrategy interface {
	Pay(amount float64)
}

type CreditCard struct{ Number string }
func (c CreditCard) Pay(amt float64) {
	fmt.Printf("Оплата %.2f руб. картой %s\n", amt, c.Number)
}

type SBP struct{ Phone string }
func (s SBP) Pay(amt float64) {
	fmt.Printf("Оплата %.2f руб. через СБП (%s)\n", amt, s.Phone)
}

func Checkout(amount float64, strategy PaymentStrategy) {
	strategy.Pay(amount)
}

func main() {
	Checkout(2500, CreditCard{Number: "*4412"})
	Checkout(1200, SBP{Phone: "+7-999-***-00"})
}

package main

import (
	"errors"
	"fmt"
	"strings"
)

type member struct {
	email string
}

func NewMember(email string) (*member, error) {
	if !strings.Contains(email, "@") {
		return nil, errors.New("некорректный email: отсутствует символ @")
	}
	return &member{email: email}, nil
}

func (m *member) Email() string { return m.email }

func main() {
	m, err := NewMember("senior@avito.ru")
	if err != nil { panic(err) }
	fmt.Println("Успешно создан участник:", m.Email())

	_, errInvalid := NewMember("bad_email")
	if errInvalid != nil {
		fmt.Println("❌ Валидация отклонила:", errInvalid)
	}
}

