import "fmt"

type LoggerMixin struct{}
func (LoggerMixin) Log(msg string) { fmt.Println("[LOG]:", msg) }

type MetricsMixin struct{}
func (MetricsMixin) Record(metric string) { fmt.Println("[METRIC]:", metric, "+1") }

type OrderService struct {
	LoggerMixin
	MetricsMixin
}

func (s *OrderService) CreateOrder(id int) {
	s.Log(fmt.Sprintf("Создание заказа #%d", id))
	s.Record("orders_created_total")
}

func main() {
	svc := &OrderService{}
	svc.CreateOrder(777)
}

package main

import (
	"fmt"
	"unsafe"
)

type SecureContainer struct {
	PublicInfo string
	secretCode int // Приватное поле
}

func NewContainer() SecureContainer {
	return SecureContainer{PublicInfo: "Открыто", secretCode: 1234}
}

func main() {
	c := NewContainer()
	fmt.Printf("До взлома: PublicInfo=%s\n", c.PublicInfo)

	// Взлом приватного поля secretCode через unsafe:
	ptr := (*int)(unsafe.Pointer(uintptr(unsafe.Pointer(&c)) + unsafe.Offsetof(c.secretCode)))
	*ptr = 9999 // Принудительная перезапись приватного поля

	fmt.Printf("После unsafe модификации secretCode=%d\n", *ptr)
}

