package main

import (
	"errors"
	"fmt"
)

type BankAccount struct{ balance int }

func NewBankAccount(init int) *BankAccount {
	if init < 0 { init = 0 }
	return &BankAccount{balance: init}
}

func (b *BankAccount) GetBalance() int { return b.balance }

func (b *BankAccount) Deposit(amt int) error {
	if amt <= 0 { return errors.New("неверная сумма") }
	b.balance += amt
	return nil
}

func (b *BankAccount) Withdraw(amt int) error {
	if amt > b.balance { return errors.New("недостаточно средств") }
	b.balance -= amt
	return nil
}

func main() {
	b := NewBankAccount(5000)
	_ = b.Deposit(2000)
	_ = b.Withdraw(1500)
	fmt.Println("Баланс:", b.GetBalance(), "копеек")
}

package main

import "fmt"

type ImmutableCounter struct {
	val int
}

func NewImmutableCounter(v int) ImmutableCounter {
	return ImmutableCounter{val: v}
}

func (c ImmutableCounter) Value() int {
	return c.val
}

// WithValue возвращает НОВЫЙ экземпляр, оригинал не меняется:
func (c ImmutableCounter) WithValue(v int) ImmutableCounter {
	return ImmutableCounter{val: v}
}

func main() {
	c1 := NewImmutableCounter(10)
	c2 := c1.WithValue(50)

	fmt.Printf("Оригинал c1: %d\n", c1.Value())
	fmt.Printf("Новый c2:     %d\n", c2.Value())
}
